});

function runSeries(tasks, finalCallback) {
  const results = [];
  let i = 0;
  function next() {
    if (i === tasks.length) return finalCallback(null, results);
    tasks[i]((err, result) => {
      if (err) return finalCallback(err);
      results.push(result);
      i++;
      next();
    });
  }
  next();
}
